package cn.zhuatech.bpm.deep;import cn.zhuatech.bpm.common.ApiResponse;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.*;
@RestController @RequestMapping("/api/admin/workflow-ops") @PreAuthorize("hasRole('ADMIN')") public class DeepWorkflowAdminController{private final DeepWorkflowService s;public DeepWorkflowAdminController(DeepWorkflowService x){s=x;}@PostMapping("/definitions")ApiResponse<?> create(@RequestBody DeepWorkflowService.DefinitionInput x){return ApiResponse.ok(s.create(x));}@PostMapping("/definitions/{id}/nodes")ApiResponse<?> node(@PathVariable Long id,@RequestBody DeepWorkflowService.NodeInput x){return ApiResponse.ok(s.addNode(id,x));}@PostMapping("/definitions/{id}/publish")ApiResponse<?> publish(@PathVariable Long id){return ApiResponse.ok(s.publish(id));}@PostMapping("/sla/escalate")ApiResponse<?> escalate(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime asOf){return ApiResponse.ok(s.escalate(asOf));}}
